SourceCode.Declaration:
/// <summary>
/// Controller for the label capture render batch.
/// Extends the SysOperation framework to run <c>AAXWHSLabelCaptureRenderService.process</c> and supports retryable batch operations.
/// </summary>
public final class AAXWHSLabelCaptureRenderController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Initializes a new instance of the <c>AAXWHSLabelCaptureRenderController</c> class.
/// </summary>
/// <param name = "_className">The name of the service class.</param>
/// <param name = "_methodName">The name of the service method.</param>
/// <param name = "_executionMode">The SysOperation execution mode.</param>
private void new(IdentifierName _className, IdentifierName _methodName, SysOperationExecutionMode _executionMode)
{
    super(_className, _methodName, _executionMode);
}

/// <summary>
/// Constructs a new instance of the <c>AAXWHSLabelCaptureRenderController</c> class.
/// Initializes the controller with the service class and method for batch processing.
/// </summary>
/// <param name = "_executionMode">The SysOperation execution mode.</param>
/// <returns>A new <c>AAXWHSLabelCaptureRenderController</c> instance.</returns>
public static AAXWHSLabelCaptureRenderController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AAXWHSLabelCaptureRenderController controller =
        new AAXWHSLabelCaptureRenderController(
            classStr(AAXWHSLabelCaptureRenderService),
            methodStr(AAXWHSLabelCaptureRenderService, process),
            _executionMode);

    return controller;
}

/// <summary>
/// Provides a description or caption for the batch task.
/// </summary>
/// <returns>A string description of the batch task.</returns>
[Hookable(false)]
public ClassDescription caption()
{
    return "@AAXWarehouseTools:CaptureRenderBatch";
}

/// <summary>
/// Gets or sets the caption of the dialog.
/// </summary>
/// <param name = "_dialogCaption">The dialog caption.</param>
/// <returns>The caption of the batch task, which is used as the dialog title.</returns>
[Hookable(false)]
public LabelType parmDialogCaption(LabelType _dialogCaption = dialogCaption)
{
    // The dialog title is based on the caption
    return this.caption();
}

/// <summary>
/// Indicates whether the batch job is retryable.
/// </summary>
/// <returns>True, indicating the batch job can be retried.</returns>
[Hookable(false)]
public boolean isRetryable()
{
    return true;
}

/// <summary>
/// Determines if the job can run in a new session.
/// </summary>
/// <returns>True if the job can run in a new session.</returns>
[Hookable(false)]
protected boolean canRunInNewSession()
{
    return true;
}

/// <summary>
/// Entry point invoked by the AAXWHSLabelCaptureRender menu item.
/// </summary>
/// <param name = "_args">Framework arguments from the caller.</param>
public static void main(Args _args)
{
    AAXWHSLabelCaptureRenderController controller = AAXWHSLabelCaptureRenderController::construct();
    controller.parmArgs(_args);
    controller.startOperation();
}
